import z3
n = 16
X = [z3.Int(f'x{i}') for i in range(n)]
s = z3.Solver()
s.add(z3.Distinct(X))
for x in X:
    s.add(x >= 0, x < n)
seen = {}
for i in range(n):
    for j in range(i+1, n):
        dr = j - i
        dc = X[j] - X[i]
        key = (dr, dc)
        if key in seen:
            s.add(z3.Or(dr != seen[key][0], dc != seen[key][1]))
        else:
            seen[key] = (dr, dc)
print(len(seen))
print(s.check())
